int orinoco_set_auth_params(struct net_device *dev, struct iw_request_info *info,
                            union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *) dev->priv;

    lock_kernel();

    switch (wrqu->data.flags & IW_AUTH_INDEX) {
    case IW_AUTH_KEY_MGMT:
        switch (wrqu->param.value) {
        case IW_AUTH_KEY_MGMT_NONE:
            priv->auth_key_mgmt = 0;
            break;
        case IW_AUTH_KEY_MGMT_802_1X:
            priv->auth_key_mgmt = 1;
            break;
        default:
            ret = -EINVAL;
        }
        break;
    case IW_AUTH_TKIP_COUNTERMEASURES:
        if (wrqu->param.value)
            priv->tkip_countermeasures = 1;
        else
            priv->tkip_countermeasures = 0;
        break;
    case IW_AUTH_ALG:
        switch (wrqu->param.value) {
        case IW_AUTH_ALG_OPEN_SYSTEM:
            priv->auth_alg = IW_AUTH_ALG_OPEN_SYSTEM;
            break;
        case IW_AUTH_ALG_SHARED_KEY:
            priv->auth_alg = IW_AUTH_ALG_SHARED_KEY;
            break;
        case IW_AUTH_ALG_LEAP:
            priv->auth_alg = IW_AUTH_ALG_LEAP;
            break;
        default:
            ret = -EINVAL;
        }
        break;
    case IW_AUTH_WPA_VERSION:
        if (wrqu->param.value & IW_AUTH_WPA_VERSION_1)
            priv->wpa_version = 1;
        else if (wrqu->param.value & IW_AUTH_WPA_VERSION_2)
            priv->wpa_version = 2;
        else
            ret = -EINVAL;
        break;
    default:
        ret = -EINVAL;
    }

    unlock_kernel();

    return ret;
}

int set_auth_parameters(struct net_device *dev, struct iw_request_info *info,
                        union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *)dev->priv;

    lock_device(dev);

    switch (wrqu->data.flags & IW_AUTH_INDEX) {
    case IW_AUTH_KEY_MGMT:
        priv->key_mgmt = wrqu->data.value;
        break;
    case IW_AUTH_TKIP_COUNTERMEASURES:
        priv->tkip_countermeasures = wrqu->data.value;
        break;
    case IW_AUTH_ALG:
        if (wrqu->data.flags & IW_AUTH_ALG_OPEN)
            priv->auth_alg |= ORINOCO_ALG_OPEN;
        else if (wrqu->data.flags & IW_AUTH_ALG_SHARED_KEY)
            priv->auth_alg |= ORINOCO_ALG_SHARED;
        else if (wrqu->data.flags & IW_AUTH_ALG_LEAP)
            priv->auth_alg |= ORINOCO_ALG_LEAP;
        else
            ret = -EINVAL;
        break;
    case IW_AUTH_WPA_VERSION:
        if (wrqu->data.value == IW_AUTH_WPA_VERSION_1)
            priv->wpa_version = ORINOCO_WPA_VERSION_1;
        else if (wrqu->data.value == IW_AUTH_WPA_VERSION_2)
            priv->wpa_version = ORINOCO_WPA_VERSION_2;
        else
            ret = -EINVAL;
        break;
    default:
        ret = -EOPNOTSUPP;
        break;
    }

    unlock_device(dev);
    return ret;
}

int set_auth_params(struct net_device *dev, struct iw_request_info *info,
                    union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *)dev->priv;

    lock_device(dev);

    if (wrqu->data.flags & IW_AUTH_KEY_MGMT) {
        if (wrqu->data.flags & IW_AUTH_KEY_MGMT_WPA) {
            priv->wpa_enabled = 1;
        } else if (wrqu->data.flags & IW_AUTH_KEY_MGMT_8021X) {
            priv->wpa_enabled = 0;
        } else {
            ret = -EINVAL;
            goto unlock;
        }
    }

    if (wrqu->data.flags & IW_AUTH_TKIP_COUNTERMEASURES) {
        if (wrqu->data.value) {
            priv->tkip_countermeasures = 1;
        } else {
            priv->tkip_countermeasures = 0;
        }
    }

    if (wrqu->data.flags & IW_AUTH_ALG) {
        if (wrqu->data.flags & IW_AUTH_ALG_OPEN_SYSTEM) {
            priv->auth_alg = AUTH_ALG_OPEN;
        } else if (wrqu->data.flags & IW_AUTH_ALG_SHARED_KEY) {
            priv->auth_alg = AUTH_ALG_SHARED;
        } else if (wrqu->data.flags & IW_AUTH_ALG_LEAP) {
            ret = -EOPNOTSUPP;
            goto unlock;
        } else {
            ret = -EINVAL;
            goto unlock;
        }
    }

    if (wrqu->data.flags & IW_AUTH_WPA_VERSION) {
        if (wrqu->data.flags & IW_AUTH_WPA_VERSION_1) {
            priv->wpa_version = WPA_VERSION_1;
        } else if (wrqu->data.flags & IW_AUTH_WPA_VERSION_2) {
            priv->wpa_version = WPA_VERSION_2;
        } else {
            ret = -EINVAL;
            goto unlock;
        }
    }

unlock:
    unlock_device(dev);
    return ret;
}

int set_auth_param(struct net_device *dev, struct iw_request_info *info,
                   union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *)dev->priv;

    if (!priv)
        return -EINVAL;

    lock_kernel();

    switch (wrqu->param.value) {
    case IEEE80211_PARAM_AUTH_ALG:
        priv->auth_alg = wrqu->param.value;
        break;
    case IEEE80211_PARAM_KEY_MGMT:
        priv->key_mgmt = wrqu->param.value;
        break;
    case IEEE80211_PARAM_TKIP_COUNTERMEASURES:
        priv->tkip_countermeasures = wrqu->param.value;
        break;
    case IEEE80211_PARAM_DROP_UNENCRYPTED:
        priv->drop_unencrypted = wrqu->param.value;
        break;
    case IEEE80211_PARAM_PRIVACY:
        priv->privacy = wrqu->param.value;
        break;
    default:
        ret = -EOPNOTSUPP;
        break;
    }

    unlock_kernel();
    return ret;
}

int orinoco_set_auth_param(struct net_device *dev, struct iw_request_info *info, union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *) dev->priv;

    lock_kernel();

    switch (wrqu->data.flags) {
        case IW_AUTH_KEY_MGMT:
            priv->auth_key_mgmt = wrqu->data.flags;
            break;
        case IW_AUTH_TKIP_COUNTERMEASURES:
            priv->tkip_countermeasures = wrqu->data.value;
            break;
        case IW_AUTH_ALGORITHM:
            if (wrqu->data.value != IW_AUTH_ALG_OPEN_SYSTEM &&
                wrqu->data.value != IW_AUTH_ALG_SHARED_KEY &&
                wrqu->data.value != IW_AUTH_ALG_LEAP)
                ret = -EINVAL;
            else
                priv->auth_alg = wrqu->data.value;
            break;
        case IW_AUTH_WPA_VERSION:
            priv->wpa_version = wrqu->data.flags;
            break;
        default:
            ret = -EOPNOTSUPP;
    }

    unlock_kernel();

    return ret;
}
